package edu.carroll.cs341.web.form;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Form class used to collect and validate a family name.
 * <p>
 * Ensures that the submitted family name is not null, contains between
 * 2 and 40 characters, and does not contain spaces.
 * <p>
 * <b>Sources Used:</b>
 * <ul>
 *   <li>ChatGPT – Assisted with generating Javadoc comments for this file
 *   in conjunction with Max Montowski.
 *   All comments were reviewed by the author. No code was generated by ChatGPT.</li>
 * </ul>
 */
public class FamilyNameForm {

    /**
     * The family name submitted by the user.
     */
    @NotNull(message = "Family Name is required")
    @Size(min = 2, message = "Family name must be at least 2 characters")
    @Size(max = 40, message = "Family name must not exceed 40 characters")
    @Pattern(regexp = "^\\S+$", message = "Family name cannot contain spaces")
    private String familyName;

    /**
     * Retrieves the submitted family name.
     *
     * @return the family name
     */
    public String getFamilyName() {
        return familyName;
    }

    /**
     * Updates the submitted family name.
     *
     * @param familyName the family name to set
     */
    public void setFamilyName(String familyName) {
        this.familyName = familyName;
    }
}
